public class OrderSummaryProjection : IProjection
{
    public async Task HandleAsync(IEvent @event, CancellationToken ct)
    {
        switch (@event)
        {
            case OrderPlaced e:
                await _db.ExecuteAsync(
                    "INSERT INTO order_summaries (order_id, customer_id, total, status, placed_at) VALUES (@Id, @CustomerId, @Total, 'Placed', @PlacedAt)",
                    e, ct);
                break;
            case OrderShipped e:
                await _db.ExecuteAsync(
                    "UPDATE order_summaries SET status = 'Shipped', shipped_at = @ShippedAt WHERE order_id = @OrderId",
                    e, ct);
                break;
        }
    }
}

class OrderProjection {
  constructor(eventBus, readDb) {
    this.eventBus = eventBus;
    this.readDb = readDb;
    this.eventBus.on('OrderPlaced', this.onOrderPlaced.bind(this));
    this.eventBus.on('OrderShipped', this.onOrderShipped.bind(this));
  }

  async onOrderPlaced({ orderId, customerId, total }) {
    await this.readDb.query(
      `INSERT INTO order_summaries (order_id, customer_id, total, status)
       VALUES ($1, $2, $3, 'Placed')`,
      [orderId, customerId, total]
    );
  }

  async onOrderShipped({ orderId, shippedAt }) {
    await this.readDb.query(
      `UPDATE order_summaries SET status = 'Shipped', shipped_at = $1 WHERE order_id = $2`,
      [shippedAt, orderId]
    );
  }
}
